  const js = `${tiltScript(style)}
var pw=document.getElementById('password');document.getElementById('show-password').onclick=function(){var show=pw.type==='password';pw.type=show?'text':'password';this.textContent=show?'Hide':'Show';this.setAttribute('aria-label',show?'Hide password':'Show password')};
var feedback=document.getElementById('feedback');document.getElementById('auth-form').addEventListener('submit',function(e){e.preventDefault();if(!this.reportValidity())return;feedback.textContent='Form looks good! Connect your authentication backend to sign users in for real.';});document.getElementById('forgot').onclick=function(e){e.preventDefault();feedback.textContent='Password reset needs to be connected to your backend.'};document.getElementById('switch-form').onclick=function(e){e.preventDefault();feedback.textContent='The other form can be added when your backend is ready.'};`;
